// ============================================================================
// USB3_2_apb: APB4 register wrapper around USB3_2_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/USB3_2.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/USB3_2.md
// ============================================================================
module USB3_2_apb #(
  parameter int MAXD    = 32,
  // payload bytes in a data packet
  parameter int TXN     = 4,
  // unacknowledged header packets (power of 2, at most 4)
  parameter int RXN     = 4,
  // receive header buffers (power of 2, at most 4)
  parameter int PEND_TO = 400,
  // PENDING_HP_TIMER, clocks
  parameter int CRED_TO = 2000
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic [7:0] tx_sym,
  output logic tx_k,
  input logic [7:0] rx_sym,
  input logic rx_k
);
  localparam logic [31:0] ID_VALUE = 32'h55330200;

  // ---------------- core ----------------
  logic          c_link_up;
  logic          c_recovery;
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic [7:0]    c_tx_data;
  logic          c_tx_last;
  logic          c_rx_valid;
  logic          c_rx_ready;
  logic [7:0]    c_rx_data;
  logic          c_rx_last;
  logic          c_rx_err;
  logic          c_ll_up;
  logic          c_ev_hp_bad;
  logic          c_ev_seq;
  logic          c_ev_lc_bad;
  logic          c_ev_dpp_bad;
  logic          c_ev_frame;
  logic          c_ev_proto;
  logic          c_ev_overflow;
  logic          c_ev_lbad;
  logic          c_ev_timeout;
  USB3_2_top #(.MAXD(MAXD), .TXN(TXN), .RXN(RXN), .PEND_TO(PEND_TO), .CRED_TO(CRED_TO)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .link_up(c_link_up),
    .recovery(c_recovery),
    .tx_sym(tx_sym),
    .tx_k(tx_k),
    .rx_sym(rx_sym),
    .rx_k(rx_k),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .tx_data(c_tx_data),
    .tx_last(c_tx_last),
    .rx_valid(c_rx_valid),
    .rx_ready(c_rx_ready),
    .rx_data(c_rx_data),
    .rx_last(c_rx_last),
    .rx_err(c_rx_err),
    .ll_up(c_ll_up),
    .ev_hp_bad(c_ev_hp_bad),
    .ev_seq(c_ev_seq),
    .ev_lc_bad(c_ev_lc_bad),
    .ev_dpp_bad(c_ev_dpp_bad),
    .ev_frame(c_ev_frame),
    .ev_proto(c_ev_proto),
    .ev_overflow(c_ev_overflow),
    .ev_lbad(c_ev_lbad),
    .ev_timeout(c_ev_timeout)
  );

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [8:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd9) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- registers ----------------
  logic [12:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [0:0] r_CTRL;   // 12'h014 CTRL
  logic [8:0] h_TX;   // 12'h018 TX holding register
  logic [9:0] h_RX;   // 12'h01C RX holding register
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 1'h0;
      h_TX <= '0;
      h_RX <= '0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[12:0] & wmask[12:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[12:0]) | (PWDATA[12:0] & wmask[12:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[6] && !full_TX) h_TX <= (h_TX & ~wmask[8:0]) | (PWDATA[8:0] & wmask[8:0]);
      if (wr && hit[6] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tx_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[7]))) begin
        h_RX[7:0] <= c_rx_data[7:0];
        h_RX[8:8] <= c_rx_last;
        h_RX[9:9] <= c_rx_err;
        avail_RX <= 1'b1;
      end else if (rd && hit[7]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_link_up = r_CTRL;
  assign c_tx_data[7:0] = h_TX[7:0];
  assign c_tx_last = h_TX[8:8];
  assign c_tx_valid = full_TX;
  assign c_rx_ready = ~avail_RX | (rd & hit[7]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_recovery;
    irq_set[1] = c_ev_hp_bad;
    irq_set[2] = c_ev_seq;
    irq_set[3] = c_ev_lc_bad;
    irq_set[4] = c_ev_dpp_bad;
    irq_set[5] = c_ev_frame;
    irq_set[6] = c_ev_proto;
    irq_set[7] = c_ev_overflow;
    irq_set[8] = c_ev_lbad;
    irq_set[9] = c_ev_timeout;
    irq_set[10] = full_TX & c_tx_ready;
    irq_set[11] = wr & (hit[6]) & full_TX;
    irq_set[12] = c_rx_valid & (~avail_RX | (rd & hit[7]));
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] rdata;
  always_comb begin
    rdata = '0;
    case (PADDR[11:2])
      10'd0: rdata = ID_VALUE;
      10'd1: rdata = 32'(irq_status);
      10'd2: rdata = 32'(irq_enable);
      10'd3: rdata = 32'(flags);
      10'd4: rdata = scratch;
      10'd5: rdata = 32'(r_CTRL);
      10'd6: rdata = 32'(h_TX);
      10'd7: rdata = 32'(h_RX);
      10'd8: rdata = 32'({c_ll_up});
      default: rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? rdata : '0;
endmodule
